"""Hidden behavioral tests for jo: booleans. Generated by pbkit from the gold binary."""


def test_at_value_00(run):
    "key@value with ''"
    r = run(args=['b@'])
    assert r.stdout == b'{"b":null}\n'
    assert r.stderr == b''
    assert r.returncode == 0


