def test_coffee_and_morning(run):
    r = run(args=['switch=true', 'morning@0'])
    assert r.stdout == b'{"switch":true,"morning":false}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_nobool_with_at(run):
    r = run(args=['-B', 'switch=true', 'morning@0'])
    assert r.stdout == b'{"switch":"true","morning":false}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_at_in_array_mode(run):
    r = run(args=['-a', 'b@1', 'c@0'])
    assert r.stdout == b'["b@1","c@0"]\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_at_nested_path(run):
    r = run(args=['a[b]@1', 'a[c]@0', 'l[]@t'])
    assert r.stdout == b'{"a":{"b":true,"c":false},"l":[true]}\n'
    assert r.stderr == b''
    assert r.returncode == 0
